# v240 (Sara 27/10 13:06): 3 more orders in Temu account 3, from her 3 receipt PDFs (קבלה 1/2/3).
# Pictures: her own store screenshots from the wishlist page where the item matches, else the receipt thumbnail.
def _t3(L,osub,total):
    R=[(n,fl,c,sz,pr,round(pr*total/osub,2),cat) for n,fl,c,sz,pr,cat in L]
    n,fl,c,sz,pr,pd,cat=R[-1]; R[-1]=(n,fl,c,sz,pr,round(pd+total-sum(x[5] for x in R),2),cat)  # rounding rest on the last line
    return R
